{
    const runtime = new DefenseCampaignRuntime()

    expect(runtime.update(5, state({
      playerDead: true,
      originalDefendersAlive: 0,
      defendersAlive: 0,
    }))).toEqual(['defeat'])
    expect(runtime.getSnapshot().phase).toBe('defeat')
    expect(runtime.getSnapshot().activePhase).toBe('deployment')
