      expect(root.scale.toArray()).toEqual([0.8, 1.1, 1.2])
      expect(root.userData.attachmentMarker).toBe('caller-owned')
      expect(unrelated.parent).toBe(root)
      expect(unrelated.geometry.type).toBe('BoxGeometry')
    }
  }

{
      const { root, tip } = build(kind, tier)
      const before = baseline[`${kind}-${tier}` as keyof typeof baseline]
      expect(root.children.length).toBe(maxMeshes)
      expect(root.children.every(child => child instanceof THREE.Mesh)).toBe(true)
      expect(root.children.length).toBeLessThan(before.meshCount)
      expect(root.userData).toEqual(before.userData)
      expect(tip?.toArray() ?? null).toEqual(before.tip)
      expect(root.userData.supportPointLocal).toBeUndefined()
      expect(root.userData.tipLocal).toBeUndefined()
      expect(root.position.toArray()).toEqual([0, 0, 0])
      expect(root.quaternion.toArray()).toEqual([0, 0, 0, 1])
      expect(root.scale.toArray()).toEqual([1, 1, 1])
      // The shield grip now stands upright for a thumb-up grasp. Normalize
      // only that intentional change to retain the historical geometry audit.
      const shieldHandle = root.getObjectByName('shield-rear-grip')
      if (shieldHandle) {
        expect(shieldHandle.rotation.z).toBe(0)
        shieldHandle.rotation.z = Math.PI / 2
      }
      if (tier === 2) expect(equipmentGeometrySignature(root)).toEqual(before.geometry)
      if (shieldHandle) shieldHandle.rotation.z = 0
      for (const child of root.children as THREE.Mesh[]) {
        expect(Array.isArray(child.material)).toBe(false)
        // Built-in primitive groups do not add draws with a single material.
        if (child.geometry.type === 'BufferGeometry' && child.name !== 'steel-sword-profiled-blade'
          && child.name !== 'roman-gladius-profiled-blade') {
          expect(child.geometry.groups).toEqual([])
          expect(child.position.toArray()).toEqual([0, 0, 0])
          expect(child.quaternion.toArray()).toEqual([0, 0, 0, 1])
          expect(child.scale.toArray()).toEqual([1, 1, 1])
          expect(child.geometry.boundingBox).not.toBeNull()
          expect(child.geometry.boundingSphere).not.toBeNull()
        }
      }
    }

{
      const a = build(kind, tier).root
      const size = proceduralMaterialCacheSize()
      const b = build(kind, tier).root
      expect(proceduralMaterialCacheSize()).toBe(size)
      const materials = (root: THREE.Group) => root.children.map(child => (child as THREE.Mesh).material)
      for (const [i, material] of materials(a).entries()) expect(material).toBe(materials(b)[i])
      polishWeaponMaterials(a)
      for (const mesh of a.children as THREE.Mesh[]) {
        expect(mesh.castShadow).toBe(true)
        expect(mesh.receiveShadow).toBe(true)
        expect(mesh.userData.originalMat).toBe(mesh.material)
      }
    }

{
    const f = await createFixture(faction), state = new ShieldState()
    const id = faction === 'roman' ? 'scutum_t2' : 'round_shield_t2'
    state.equip(id)
    const collider = new ShieldCollider(f.shield, state); collider.setModel(id)
    const legPose = () => f.rigs.flatMap(r => [r.leftLeg.hip, r.leftLeg.knee, r.rightLeg.hip, r.rightLeg.knee].flatMap(b => b.quaternion.toArray()))
    f.reset(true, false, 2)
    f.animator.setShieldRaised(false); f.animator.update(0)
    const lower = legPose()
    const low = f.shield.getWorldPosition(new THREE.Vector3())
    f.animator.setShieldRaised(true); f.animator.update(0)
    expect(legPose()).toEqual(lower)
    const center = f.shield.getWorldPosition(new THREE.Vector3())
    expect(center.y).toBeGreaterThan(low.y)
    expect(collider.time(new THREE.Vector3(0, center.y, 2), new THREE.Vector3(0, center.y, -2))).toBeLessThan(1)
    expect(collider.time(new THREE.Vector3(0, .1, 2), new THREE.Vector3(0, .1, -2))).toBe(Infinity)
    f.animator.setShieldRaised(false)
  }

{
    const f = await createFixture(faction)
    const frames = f.levels.map(l => l.scene.userData.equipmentGripFrames.shieldLeft)
    const bindChest = f.rigs.map(r => r.upperChest!.getWorldQuaternion(new THREE.Quaternion()))
    for (const mounted of [false, true]) for (const action of ['swordSlash', 'axeAttack1H'] as const) {
      if (faction === 'roman' && action === 'axeAttack1H') continue // Axe clips are Viking-only.
      f.root.rotation.y = mounted ? 1.2 : -.7
      f.reset(true, mounted)
      f.animator.setEquipment(false, true)
      const localGrips = f.rigs.map((r, i) => r.upperChest!.worldToLocal(r.left.wrist.localToWorld(new THREE.Vector3(...frames[i].gripCenterLocal))))
      const startNormal = new THREE.Vector3(0, 0, 1).transformDirection(f.shield.matrixWorld)
      let maxTurn = 0
      f.animator.start(action)
      for (let sample = 0; sample < 75; sample++) {
        f.animator.update(1 / 120)
        const measured = f.measure()
        maxTurn = Math.max(maxTurn, startNormal.angleTo(new THREE.Vector3(0, 0, 1).transformDirection(f.shield.matrixWorld)))
        f.rigs.forEach((rig, i) => {
          const chestInverse = rig.upperChest!.getWorldQuaternion(new THREE.Quaternion()).invert()
          const thumb = new THREE.Vector3(...frames[i].gripAxisLocal).transformDirection(rig.left.wrist.matrixWorld).applyQuaternion(chestInverse).applyQuaternion(bindChest[i])
          const palm = new THREE.Vector3(...frames[i].palmNormalLocal).transformDirection(rig.left.wrist.matrixWorld).applyQuaternion(chestInverse).applyQuaternion(bindChest[i])
          expect(thumb.y, `${action} mounted=${mounted} sample=${sample} LOD${i}`).toBeGreaterThan(.999)
          expect(palm.x).toBeLessThan(-.999)
          expect(rig.upperChest!.worldToLocal(measured.hands[i].shield.clone()).distanceTo(localGrips[i])).toBeLessThan(.001)
          expect(measured.hands[i].shield.distanceTo(measured.shieldGrip)).toBeLessThan(.01)
        })
      }
      expect(maxTurn).toBeGreaterThan(.15)
    }
  }

{
    const sword = await createFixture(faction), lance = fixtures[faction]
    for (const mounted of [false, true]) for (const shield of [false, true]) for (const speed of [0, 2, 4]) {
      for (const f of [sword, lance]) { f.controller.stop(); f.animator.cancel(); f.animator.setEquipment(f === lance, shield); f.animator.setLocomotion(speed, mounted) }
      for (let i = 0; i < 60; i++) {
        const dt = i % 3 ? 1 / 60 : 0
        sword.animator.update(dt); lance.animator.update(dt)
        expect(bones(lance)).toEqual(bones(sword))
      }
    }
  }

{
    const f = fixtures[faction]
    for (const yaw of [0, Math.PI / 2, Math.PI, -Math.PI / 2]) {
      f.root.rotation.y = yaw; f.reset(false)
      const matrix = f.lance.matrix.clone()
      for (let i = 0; i < 180; i++) {
        f.animator.update(1 / 60)
        const m = f.measure()
        expect(m.hands[0].right.distanceTo(m.grip)).toBeLessThan(.00001)
        expect(m.tip.clone().sub(m.grip).normalize().dot(new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw)))).toBeGreaterThan(.95)
        expect(f.lance.matrix.equals(matrix)).toBe(true)
      }
    }
    f.root.rotation.y = 0
  }

{
    const f = fixtures[faction]
    f.controller.stop(); f.controller.setEquipmentState({ lance: false, shield: false, mounted: false })
    f.controller.play('idle', { fadeSeconds: 0 }); f.controller.seek('idle', .25)
    const baseline = bones(f)
    for (let i = 0; i < 20; i++) {
      f.controller.setEquipmentState({ lance: i % 2 === 0 }); f.controller.seek('idle', .25); f.controller.update(0)
      expect(bones(f)).toEqual(baseline)
    }
  }

{
    const f = fixtures[faction]; f.reset(true)
    expect(f.animator.start('bowRelease')).toBe(false)
    expect(f.animator.start('greatswordSlash')).toBe(false)
    f.animator.start('lanceThrust')
