        [npc],
        [npc],
        [],
        null as any,
        () => {},
        () => {},
        true
      )
    }
    expect(npc.state).toBe(AIState.DEAD)
    expect(npc.dead).toBe(true)

    // Advance another 6 seconds (total 11s > 10.0s RESPAWN_TIME) -> should respawn
    for (let step = 0; step < 6; step++) {
      npc.update(
        1.0,
        player,
        [npc],
        [npc],
        [],
        null as any,
        () => {},
        () => {},
        true
      )
    }
    expect(npc.state).not.toBe(AIState.DEAD)
