test_body:
{
    const scene = new THREE.Scene(), navigation = new NavigationWorld(), player = playerFixture(), step = loadingFrames()
    const profile = { ...createCareerProfile('roman'), rank: 'captain' as const,
      personalSquad: { members: Array.from({ length: 30 }, (_, i) => ({ id: `personal:shared-${i}`, type: 'soldier' as const })) } }
    const personal = new PersonalSquadRuntime(scene, Array.from({ length: 30 }, (_, i) => ({ x: i * 5, z: -30, yaw: 0 })), () => profile, () => player)
    personal.follow()
    const missionProfile = { ...createCareerProfile('roman'), activeMission: createActiveCareerMission(templateId, 0, enemyCount, 0, 'shared-mission') }
    const world = { camps: Array.from({ length: 5 }, (_, i) => ({ spawnPoints: [new THREE.Vector3(120 + i * 10, 0, 120)] })), obstacles: [] } as any
    const mission = new BanditMissionController(scene, world, navigation, {} as NPC, [], () => player, () => missionProfile, () => true)
    expect(mission.startActiveMission()).toBe(true)
    const outskirts = new TownOutskirtsWarfareController(scene, 'roman', () => profile, [], navigation)
    const game = gameFixture(), loading = game._executeBattleSpawnPlan({ npcSpecs: [{ x: 0, z: 0, faction: Faction.PLAYER, characterFaction: 'roman', aiType: AIType.MELEE, name: 'loading', tier: 1, cavalry: false, respawnEnabled: false }], pickupSpecs: [], horseSpecs: [], playerSpawn: { x: 0, z: 0 } })
    dispose.push(() => personal.cleanup(), () => mission.dispose(), () => outskirts.dispose())
    expect(observed.constructors).toHaveLength(0); expect(mission.ready).toBe(false)
    expect(mission.evaluate(true)).toBeNull()
    for (let frame = 0; frame < 110 && gameplayNpcSpawns.pending; frame++) await step()
    await loading
    expect(personal.actors).toHaveLength(30); expect(mission.missionBandits).toHaveLength(enemyCount)
    expect(outskirts.actors).toHaveLength(60); expect(game.npcs).toHaveLength(1)
    expect(new Set(observed.constructors).size).toBe(observed.constructors.length)
    const before = observed.constructors.length
    const cavalry = outskirts.squads.find(squad => squad.spec.kind === 'cavalry')!
    cavalry.members.forEach(npc => { (npc as any).dead = true })
    outskirts.prepareFrame(0, outskirts.actors, player)
    personal.cleanup(); personal.follow(); mission.cleanupMission(0)
    expect(observed.constructors).toHaveLength(before)
    for (let frame = 0; frame < 45 && gameplayNpcSpawns.pending; frame++) await step()
    expect(cavalry.members).toHaveLength(10); expect(mission.ambientBandits.filter(npc => npc.combatantId.startsWith('ambient:0:'))).toHaveLength(2)
    expect(personal.actors).toHaveLength(30)
  }

{
      const col = new NpcSubphaseCollector()

      // Simulate: targetAI took 0.5ms, separation took 1.2ms
      const fakeT0A = performance.now() - 0.5
      col.endPhase('targetAI', fakeT0A)
      const fakeT0S = performance.now() - 1.2
      col.endPhase('separation', fakeT0S)

      // After one frame the values haven't been flushed yet
      const pending = (col as any)._window
      expect(pending.targetAI).toBeGreaterThanOrEqual(0.45)
      expect(pending.separation).toBeGreaterThanOrEqual(1.1)
      expect(pending.mountUpdate).toBe(0)
    }

{
      const col = new NpcSubphaseCollector()
      col.countSample()
      col.countSample()
      expect((col as any)._window.sampleCount).toBe(2)
    }

{
      const col = new NpcSubphaseCollector()
      col.endPhase('targetAI', performance.now() - 1)
      col.countSample()

      // SUBPHASE_COHORT - 1 frames → no flush yet
      for (let i = 0; i < SUBPHASE_COHORT - 1; i++) {
        expect(col.advanceFrame()).toBeNull()
      }

      // The SUBPHASE_COHORT-th frame triggers the flush
      const result = col.advanceFrame()
      expect(result).not.toBeNull()
      expect(result!.sampleCount).toBe(1)
      expect(result!.targetAI).toBeGreaterThan(0)
    }

{
      const col = new NpcSubphaseCollector()
      col.endPhase('mountUpdate', performance.now() - 2)
      col.countSample()
      for (let i = 0; i < SUBPHASE_COHORT; i++) col.advanceFrame()

      // After flush, internal window should be zeroed
      const w = (col as any)._window
      expect(w.mountUpdate).toBe(0)
      expect(w.sampleCount).toBe(0)
      expect((col as any)._framesInWindow).toBe(0)
    }

{
      const col = new NpcSubphaseCollector()
      col.endPhase('footPhysics', performance.now() - 5)
      col.countSample()
      col.advanceFrame() // 1 frame in
      col.reset()
      expect((col as any)._window.footPhysics).toBe(0)
      expect((col as any)._framesInWindow).toBe(0)
    }

{
      const totalNPCs = 200
      const sampledPerFrame: Set<number>[] = []

      for (let frameIdx = 0; frameIdx < SUBPHASE_COHORT; frameIdx++) {
        const sampled = new Set<number>()
        for (let npcIdx = 0; npcIdx < totalNPCs; npcIdx++) {
          if (npcIdx % SUBPHASE_COHORT === frameIdx % SUBPHASE_COHORT) {
            sampled.add(npcIdx)
          }
        }
        sampledPerFrame.push(sampled)
      }

      // No duplicates between frames
      const allSampled = new Set<number>()
      let totalSampled = 0
      for (const frameSet of sampledPerFrame) {
        for (const idx of frameSet) {
          expect(allSampled.has(idx)).toBe(false)
          allSampled.add(idx)
          totalSampled++
        }
      }

      // Every NPC covered exactly once
      expect(totalSampled).toBe(totalNPCs)
      expect(allSampled.size).toBe(totalNPCs)
    }

{
      // Run the cohort condition twice; results must be identical
      const results1: boolean[] = []
      const results2: boolean[] = []
      for (let frame = 0; frame < SUBPHASE_COHORT; frame++) {
        for (let npc = 0; npc < 16; npc++) {
          results1.push(npc % SUBPHASE_COHORT === frame % SUBPHASE_COHORT)
        }
      }
      for (let frame = 0; frame < SUBPHASE_COHORT; frame++) {
        for (let npc = 0; npc < 16; npc++) {
          results2.push(npc % SUBPHASE_COHORT === frame % SUBPHASE_COHORT)
        }
      }
      expect(results1).toEqual(results2)
    }

{
      const agg = new NpcSubphaseAggregator()

      // Simulate one 8-frame window result
      agg.record({
        gridQuery: 0.8,
        targetAI: 1.2,
        separation: 2.1,
        obstacleAvoid: 3.0,
        moveFace: 0.5,
        combatLogic: 0.4,
        humanoidAnim: 4.5,
        mountUpdate: 5.0,
        footPhysics: 0.1,
        deadUpdate: 0.3,
        sampleCount: 25,
      })

      const snap = agg.flush()
      expect(snap).not.toBeNull()
      expect(snap!.humanoidAnim.avg).toBeCloseTo(4.5, 3)
      expect(snap!.mountUpdate.avg).toBeCloseTo(5.0, 3)
      expect(snap!.separation.avg).toBeCloseTo(2.1, 3)
      expect(snap!.sampleCountAvg).toBeCloseTo(25, 3)
    }

{
      const agg = new NpcSubphaseAggregator()

      agg.record({
        gridQuery: 1, targetAI: 2, separation: 3, obstacleAvoid: 4,
        moveFace: 5, combatLogic: 6, humanoidAnim: 7, mountUpdate: 8,
        footPhysics: 9, deadUpdate: 10, sampleCount: 20,
      })
      agg.flush() // consume first window

      // Second window with different values
      agg.record({
        gridQuery: 0.1, targetAI: 0.2, separation: 0.3, obstacleAvoid: 0.4,
        moveFace: 0.5, combatLogic: 0.6, humanoidAnim: 0.7, mountUpdate: 0.8,
        footPhysics: 0.9, deadUpdate: 1.0, sampleCount: 5,
      })
      const snap2 = agg.flush()
      expect(snap2).not.toBeNull()
      // Must not carry over values from the first window
      expect(snap2!.humanoidAnim.avg).toBeCloseTo(0.7, 3)
      expect(snap2!.mountUpdate.avg).toBeCloseTo(0.8, 3)
    }

{
      const agg = new NpcSubphaseAggregator()
      expect(agg.flush()).toBeNull()
    }

{
      const agg = new NpcSubphaseAggregator()
      const frame = (humanoidAnim: number) => ({
        gridQuery: 0, targetAI: 0, separation: 0, obstacleAvoid: 0,
        moveFace: 0, combatLogic: 0, humanoidAnim, mountUpdate: 0,
        footPhysics: 0, deadUpdate: 0, sampleCount: 200,
      })
      agg.record(frame(4))
      agg.record(frame(8))

      const snap = agg.flush()
      expect(snap!.humanoidAnim.avg).toBeCloseTo(6, 3)
      expect(snap!.humanoidAnim.max).toBeCloseTo(8, 3)
      expect(snap!.sampleCountAvg).toBeCloseTo(200, 3)
    }

{
      expect(SUBPHASE_COHORT).toBe(8)
    }

{
    expect(TERRAIN_SIZE).toBe(640)
    expect(PLAYABLE_WORLD_BOUND).toBe(300)
    expect(TERRAIN_SIZE / 2 - PLAYABLE_WORLD_BOUND).toBe(20)
  }

{
    const position = new THREE.Vector3(150, 7, -150)

    clampToPlayableWorld(position)

    expect(position.x).toBe(150)
    expect(position.y).toBe(7)
    expect(position.z).toBe(-150)
  }

{
    const position = new THREE.Vector3(350, 12, -340)

    clampToPlayableWorld(position)

    expect(position.x).toBe(PLAYABLE_WORLD_BOUND)
    expect(position.y).toBe(12)
    expect(position.z).toBe(-PLAYABLE_WORLD_BOUND)
  }

{
    const scene = new THREE.Scene()
    const mount = new Mount(scene, MountType.CORGI, PLAYABLE_WORLD_BOUND - 0.5, 0)

    mount.beginControlledFrame()
    mount.addControlledMovement(new THREE.Vector3(1, 0, 0), 20, 0.1)
    mount.finishControlledFrame(0.1, [])

    expect(mount.group.position.x).toBe(PLAYABLE_WORLD_BOUND)
    expect(Math.abs(mount.group.position.z)).toBeLessThanOrEqual(PLAYABLE_WORLD_BOUND)
  }

{
      const scene = new THREE.Scene()
      const player = new Player(scene)
      const mockHpBar = { setFill: vi.fn() } as any
      const deathCallback = vi.fn()
      player.onPlayerDeath = deathCallback

      player.group.position.set(20, 0, 30)
      player.spawnX = 0
      player.spawnZ = 0

      expect(player.dead).toBe(false)
      expect(player.hp).toBe(200)

      // Apply fatal damage
      const hit = player.takeDamage(250, mockHpBar)
      expect(hit).toBe(true)
      expect(player.dead).toBe(true)
      expect(player.hp).toBe(0)
      expect(deathCallback).toHaveBeenCalledTimes(1)
      expect(mockHpBar.setFill).toHaveBeenCalledWith(0)
      expect(player.group.rotation.z).toBe(0)

      // Subsequent damage to dead player should return false and not fire callback again
      const extraHit = player.takeDamage(50, mockHpBar)
      expect(extraHit).toBe(false)
      expect(deathCallback).toHaveBeenCalledTimes(1)

      // Advance frames across several seconds: player must remain dead at position, never resetting to spawn
      const mockInput = createMockInput() as any
      const aimPoint = new THREE.Vector3(0, 0, 0)
      const staminaBar = { setFill: vi.fn() } as any
      const quiverUI = { setAiming: vi.fn(), setChargeRatio: vi.fn(), setShieldBlocked: vi.fn() } as any
      const soundManager = { playSwing: vi.fn(), playHit: vi.fn() } as any

      for (let i = 0; i < 180; i++) {
        player.update(
          0.016,
          mockInput,
          0,
          aimPoint,
          [],
          staminaBar,
          quiverUI,
          soundManager
        )
      }

      expect(player.dead).toBe(true)
      expect(player.hp).toBe(0)
      expect(player.group.rotation.z).toBe(0)
      // Coordinates remain near death point (20, 30), NOT reset to spawn (0, 0)
      expect(player.position.x).toBeCloseTo(20, 0)
      expect(player.position.z).toBeCloseTo(30, 0)
    }

{
      const scene = new THREE.Scene()
      const player = new Player(scene)
      const mount = new Mount(scene, MountType.CORGI, 10, 20)
      player.mountVehicle(mount, 0)

      const seatPosBeforeDeath = player.position.clone()
      expect(player.isMounted).toBe(true)

      // Trigger dedicated death detach
      player.detachFromMountOnDeath()

      expect(player.isMounted).toBe(false)
      expect(player.currentMount).toBeNull()
      // Position is preserved at rider seat height, NOT teleported to ground or reset
      expect(player.position.x).toBeCloseTo(seatPosBeforeDeath.x, 2)
      expect(player.position.y).toBeCloseTo(seatPosBeforeDeath.y, 2)
      expect(player.position.z).toBeCloseTo(seatPosBeforeDeath.z, 2)
    }

{
      const activeCamera = new THREE.PerspectiveCamera(58, 16 / 9, 0.1, 1000)
      activeCamera.position.set(12.5, 4.2, -35.8)
      activeCamera.rotation.set(-0.2, 1.1, 0, 'YXZ')
      activeCamera.updateMatrixWorld(true)

      const spectatorCamera = new THREE.PerspectiveCamera(58, 16 / 9, 0.1, 1000)
