test_body:
{
    const { controller, profile, player, scene } = harness(); completeNpcDeployment(() => controller.follow(), gameplayNpcSpawnDriver)
    const mission = createActiveCareerMission('recruit-bandits-01', 0, 3, 0)
    mission.phase = 'ENGAGING'; mission.personalSquad = controller.captureForMission(snapshotPersonalMission(profile)!)
    const events = new CombatEventStream(), observed: unknown[] = []
    events.subscribe(event => observed.push(event))
    const tracker = new BattleStatsTracker(events, true, undefined, {}, careerMissionCommandMeritPolicy(mission))
    cleanups.push(() => tracker.dispose())
    const enemy = new NPC(scene, 0, 0, Faction.BANDIT, 'viking', AIType.MELEE, 'bandit', 2,
      false, { meleeWeaponId: 'viking_axe_t1', shieldId: null }, 'viking_berserker', undefined, mission.targetActorIds[0])
    enemy.restoreCombatHealth(17); cleanups.push(() => enemy.dispose())
    const town = Object.assign(createTownCombatFixture(), {
      scene, profile, player, personalSquad: controller, event: { hostile: false }, residents: [], shots: [],
      world: { obstacles: [], targets: [], buildings: [] }, defense: { active: false },
      mission: { events, friendlies: [], ambientBandits: [], missionBandits: [enemy], combatPeersFor: () => [enemy], alertGroupFor: vi.fn() },
      awardCareerSkillXp: vi.fn(), inventory: {},
    })
    const shooter = controller.actors[2], origin = enemy.combatPosition.clone().add(new THREE.Vector3(-2, 1, 0))
    town.fire(origin, new THREE.Vector3(1, 0, 0), 40, 100, false, false, 'arrow', shooter)
    expect(town.shots[0].sourceRef).toMatchObject({ actorType: 'npc', actorId: 'personal:2', squadId: 'personal', ownership: 'player-personal' })
    shooter.takeDamage(99999); controller.cleanup()
    shooter.combatOwnership = undefined
    town.updateShots(.1)
    expect(enemy.dead).toBe(true); expect(town.shots).toHaveLength(0)
    expect(observed).toHaveLength(2)
    expect(observed[0]).toMatchObject({ source: { actorType: 'npc', actorId: 'personal:2', squadId: 'personal', ownership: 'player-personal' }, appliedDamage: 17 })
    expect(tracker.commandCheckpoint()).toMatchObject({ damageDealt: 17, kills: 1 })
    expect(tracker.checkpoint()).toMatchObject({ damageDealt: 0, kills: 0 })
    expect(town.awardCareerSkillXp).not.toHaveBeenCalled()
  }

{
    const f = fixture()
    const cameraBefore = f.camera.matrixWorld.clone()
    const disposeGeometry = vi.spyOn(f.geometry, 'dispose')
    const disposeMaterial = vi.spyOn(f.material, 'dispose')
    const disposeTarget = vi.spyOn(THREE.WebGLRenderTarget.prototype, 'dispose')
    try {
      await f.warm()
      expect(f.draws).toEqual([
        ['humanoid-lod0', 'mount-lod0', 'equipment-detail'],
        ['humanoid-lod1', 'mount-lod1'],
        ['humanoid-lod2', 'mount-lod2'],
      ])
      expect(f.renderer.compileAsync).toHaveBeenCalledTimes(6)
      expect(f.yieldFrame).toHaveBeenCalledTimes(3)
      expect(f.lodHook).toHaveBeenCalledTimes(4)
      expect(f.camera.matrixWorld.equals(cameraBefore)).toBe(true)
      expect(disposeGeometry).not.toHaveBeenCalled()
      expect(disposeMaterial).not.toHaveBeenCalled()
      expect(disposeTarget).toHaveBeenCalledTimes(1)
      expectRestored(f)
    } finally { disposeTarget.mockRestore() }
  }

{
    const f = fixture()
    const geometry = new THREE.BoxGeometry()
    const vertices = geometry.attributes.position.count
    geometry.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(new Uint16Array(vertices * 4), 4))
    const weights = new Float32Array(vertices * 4)
    for (let index = 0; index < vertices; index++) weights[index * 4] = 1
    geometry.setAttribute('skinWeight', new THREE.Float32BufferAttribute(weights, 4))
    const lod = new THREE.LOD()
    lod.position.set(70, 0, -6)
    const meshes = [0, 28, 60].map(distance => {
      const mesh = new THREE.SkinnedMesh(geometry, f.material)
      const bone = new THREE.Bone()
      mesh.add(bone)
      mesh.bind(new THREE.Skeleton([bone]))
      lod.addLevel(mesh, distance)
      return mesh
    })
    f.scene.add(lod)
    const compute = meshes.map(mesh => vi.spyOn(mesh, 'computeBoundingSphere'))
    await f.warm()
    for (const [index, mesh] of meshes.entries()) {
      expect(compute[index]).toHaveBeenCalledTimes(1)
      expect(mesh.boundingSphere!.radius).toBeGreaterThan(0)
      expect(Number.isFinite(mesh.boundingSphere!.radius)).toBe(true)
    }
    expectRestored(f)
  }

{
    const first = fixture()
    const second = fixture()
    await first.warm()
    await second.warm()
    expect(first.draws).toHaveLength(3)
    expect(second.draws).toHaveLength(3)
    expectRestored(first)
    expectRestored(second)
  }

{
    const f = fixture()
    const error = new Error('warmup failed')
    if (stage === 'compile') f.renderer.compileAsync.mockRejectedValueOnce(error)
    else if (stage === 'render') f.renderer.render.mockImplementationOnce(() => { throw error })
    else f.yieldFrame.mockRejectedValueOnce(error)
    const disposeTarget = vi.spyOn(THREE.WebGLRenderTarget.prototype, 'dispose')
    try {
      await expect(f.warm()).rejects.toBe(error)
      expectRestored(f)
      expect(disposeTarget).toHaveBeenCalledTimes(1)
    } finally { disposeTarget.mockRestore() }
  }

{
    const obstacles: ObstacleData[] = [], material = new THREE.MeshBasicMaterial()
    const city = createTownFortifications(faction, obstacles, { stone: material, wood: material, dark: material, snow: material })
    const gate = city.gates.get(id)!, outward = siegeOutward(id)
    const bodies = [0.6, 0.5, 1.5].map((radius, index) => {
      const position = siegePoint(id, index - 1, 0)
      return { position, radius, hp: 100, moveTo: vi.fn((point: THREE.Vector3) => position.copy(point)) }
    })
    const untouched = [-20, 20].map(inward => {
      const position = siegePoint(id, 0, inward)
      return { position, radius: .6, hp: 100, moveTo: vi.fn() }
    })
    const hp = gate.damageable.currentHp
    expect(closeSiegeGate(id, gate, [...bodies, ...untouched], obstacles)).toBe(true)
    expect(gate.state).toBe('closed')
    expect(gate.damageable.currentHp).toBe(hp)
    for (const body of bodies) {
      expect(body.moveTo).toHaveBeenCalledOnce()
      expect(body.position.clone().sub(siegePoint(id, 0, 0)).dot(outward)).toBeGreaterThan(body.radius)
      expect(obstacles.some(o => overlapsGateClosure(o.navigationBox ?? o.box, body.position, body.radius))).toBe(false)
      expect(body.hp).toBe(100)
    }
    for (const body of untouched) expect(body.moveTo).not.toHaveBeenCalled()
    material.dispose()
  }

{
    const current = { ...profile(rank), availableMerit: 2000 }
    const result = purchaseTownEquipment(current, id)
    expect(result.purchased).toBe(allowed)
    expect(result.purchased).toBe(TOWN_PRODUCTS.find(p => p.id === id)!.tier <= getCareerPurchaseTier(rank))
    if (!allowed) { expect(result.reason).toBe('tier-locked'); expect(result.profile).toEqual(current) }
  }

{
    const current = profile(); current.equipment = { melee: 'gladius_rusty' }
    const before = structuredClone(current)
    const result = purchaseTownEquipment(current, 'steel_sword')
    expect(result).toMatchObject({ purchased: true, spentMerit: 400, profile: { totalMerit: 800, availableMerit: 100, ownedWeapons: ['gladius_rusty', 'steel_sword'], equipment: current.equipment, starterWeaponId: 'gladius_rusty' } })
    expect(current).toEqual(before)
    const duplicate = purchaseTownEquipment(result.profile, 'steel_sword')
    expect(duplicate.reason).toBe('insufficient-merit'); expect(duplicate.profile).toEqual(result.profile)
    const repeated = purchaseTownEquipment({ ...result.profile, availableMerit: 500 }, 'steel_sword')
    expect(repeated.purchased).toBe(true); expect(careerItemTotal(repeated.profile, 'steel_sword')).toBe(2)
  }

{
    const current = profile(); current.availableMerit = 399
    const insufficient = purchaseTownEquipment(current, 'steel_sword')
    expect(insufficient.reason).toBe('insufficient-merit'); expect(insufficient.profile).toEqual(current)
    for (const id of ['missing', '', 'horse-t1', { id: 'steel_sword', price: 0, tier: 1, category: 'armor' }]) {
      const rejected = purchaseTownEquipment(current, id as string)
      expect(rejected.reason).toBe('invalid-id'); expect(rejected.profile).toEqual(current)
    }
    // Extra JS arguments cannot override the canonical fields.
    const call = purchaseTownEquipment as (...args: unknown[]) => ReturnType<typeof purchaseTownEquipment>
    const locked = call(profile('recruit'), 'steel_sword', { price: 0, tier: 1, category: 'armor' })
    expect(locked.reason).toBe('tier-locked')
    const canonical = call(profile(), 'steel_sword', { price: 0, tier: 1, category: 'armor' })
    expect(canonical.spentMerit).toBe(400); expect(canonical.profile.ownedArmors).toEqual([])
    expect(canonical.profile.ownedWeapons).toContain('steel_sword')
  }

{
    expect(TOWN_PRODUCTS.some(p => p.id === id)).toBe(false)
    const current = profile('commander')
    expect(purchaseTownEquipment(current, id)).toMatchObject({ purchased: false, profile: current, reason: 'invalid-id' })
  }

{
    for (const item of TOWN_PRODUCTS.filter(p => p.category !== 'mount')) expect(item.price).toBe(item.tier ** 2 * (item.category === 'weapon' ? 100 : 90))
    expect(purchaseTownEquipment(profile(), 'viking_axe_t2').purchased).toBe(true)
    expect(purchaseTownEquipment({ ...profile(), faction: 'viking' }, 'pilum_standard').purchased).toBe(true)
  }

{
    let current = profile()
    const inventory = new TownEquipment(() => current, next => { current = next; return true })
    expect(inventory.inventoryStacks.some(s => s.item.id === id)).toBe(false)
    current = purchaseTownEquipment(current, id).profile
    expect(inventory.isEquipped(id)).toBe(false)
    expect(inventory.inventoryStacks.find(s => s.item.id === id)?.quantity).toBe(1)
    expect(inventory.equipWeapon(id)).toBe(true)
    expect(Object.values(current.equipment!)).toContain(id)
    expect(inventory.inventoryStacks.find(s => s.item.id === id)?.quantity).toBe(1)
  }

{
    let current = profile()
    const ready = new TownEquipment(() => current, next => { current = next; return true })
    current = purchaseTownEquipment(current, 'recurve_longbow').profile
    expect(ready.equipWeapon('recurve_longbow')).toBe(true)
    current.availableMerit = 500
    const inventory = new TownEquipment(() => current, () => false)
    current = purchaseTownEquipment(current, 'steel_sword').profile
    expect(inventory.equipWeapon('steel_sword')).toBe(false)
    expect(inventory.isEquipped('steel_sword')).toBe(false)
    expect(current.equipment).toEqual({ melee: 'gladius_rusty', ranged: 'recurve_longbow', shield: null })
  }

{
    const store = new CareerProfileStore(storage())
    let current = profile(); current.totalMerit = 2000; current.availableMerit = 2000
    const inventory = new TownEquipment(() => current, next => { if (!store.save(next)) return false; current = next; return true })
    for (const id of ['steel_sword', 'recurve_longbow', 'scutum_t2']) {
      const result = purchaseTownEquipment(current, id)
      expect(result.purchased).toBe(true); expect(store.save(result.profile)).toBe(true); current = result.profile
      expect(inventory.equipWeapon(id)).toBe(true)
    }
    const reloaded = store.load()!
    expect(reloaded.totalMerit).toBe(2000); expect(reloaded.availableMerit).toBe(840)
    expect(reloaded.ownedWeapons).toEqual(['gladius_rusty', 'steel_sword', 'recurve_longbow'])
    expect(reloaded.ownedArmors).toEqual(['scutum_t2'])
    expect(careerItemTotal(purchaseTownEquipment(reloaded, 'steel_sword').profile, 'steel_sword')).toBe(2)
    const launch = createCareerOutpostLaunch(acceptCareerOutpost(reloaded, 1, 'shop-outpost')!)
    const expected = { meleeWeaponId: 'steel_sword', rangedWeaponId: 'recurve_longbow', shieldId: 'scutum_t2' }
